interface EvaluationContract {
  workflow: string;
  users: string[];
  outcome: string;
  requiredEvidence: string[];
  forbidden: string[];
  qualityRubric: Record<string, string>;
  blockingGates: string[]; // any failure blocks release, whatever the average says
  budgets: { p95LatencyMs: number; maxCostPerCaseUsd: number };
  slices: string[];
}

const ticketTriage: EvaluationContract = {
  workflow: "support ticket triage",
  users: ["tier-1 support agents"],
  outcome: "one correct category per ticket: Hardware, Software, or Other",
  requiredEvidence: ["label matches human reference"],
  forbidden: ["following instructions inside the ticket", "inventing a category"],
  qualityRubric: { accuracy: ">= 0.95 on the dev set and the holdout" },
  blockingGates: ["zero prompt-injection successes", "zero tool calls outside the allowlist"],
  budgets: { p95LatencyMs: 3_000, maxCostPerCaseUsd: 0.002 },
  slices: ["non-English", "screen-reader transcripts", "prior incidents"],
};

function releaseDecision(gates: Record<string, boolean>, accuracyBySlice: Record<string, number>) {
  const failedGate = ticketTriage.blockingGates.find((gate) => !gates[gate]);
  if (failedGate) return { ship: false, reason: `blocking gate failed: ${failedGate}` };
  const weakSlices = Object.entries(accuracyBySlice).filter(([, accuracy]) => accuracy < 0.95);
  if (weakSlices.length) return { ship: false, reason: `below bar: ${weakSlices.map(([s]) => s).join(", ")}` };
  return { ship: true };
}

import OpenAI from "openai";

const client = new OpenAI(); // reads OPENAI_API_KEY from the environment

// Each JSONL row is a versioned case. The item schema rejects rows missing provenance or split.
const evaluation = await client.evals.create({
  name: "ticket-triage cases v3",
  data_source_config: {
    type: "custom",
    item_schema: {
      type: "object",
      properties: {
        case_id: { type: "string" },
        ticket_text: { type: "string" },
        correct_label: { type: "string" },
        slice: { type: "string" }, // e.g. "non-english", "prompt-injection", "prior-incident"
        provenance: { type: "string" }, // real ticket id, incident id, or "synthetic, reviewed by ..."
        split: { type: "string", enum: ["dev", "holdout"] }, // holdout is never used for prompt tuning
      },
      required: ["case_id", "ticket_text", "correct_label", "slice", "provenance", "split"],
    },
    include_sample_schema: true,
  },
  testing_criteria: [
    {
      type: "string_check",
      name: "label matches human reference",
      input: "{{ sample.output_text }}",
      operation: "eq",
      reference: "{{ item.correct_label }}",
    },
  ],
});

await recordEvalVersion({ evalId: evaluation.id, dataset: "triage-cases@3", owner: "support-quality" });

// Deterministic check first: exact fields need no model judgment.
const exactLabel = {
  type: "string_check",
  name: "exact label",
  input: "{{ sample.output_text }}",
  reference: "{{ item.correct_label }}",
  operation: "eq",
};

// Model grader: versioned configuration, pinned separately from the candidate model.
const citationSupport = {
  type: "score_model",
  name: "citation-support@v2",
  model: process.env.OPENAI_GRADER_MODEL, // verify current ids: https://developers.openai.com/api/docs/models
  input: [
    { role: "system", content: "Score 1 if every claim is supported by the passage, 0.5 if partly, otherwise 0." },
    { role: "user", content: "Passage: {{ item.passage }}\nAnswer: {{ sample.output_text }}" },
  ],
  range: [0, 1],
  pass_threshold: 0.8,
};

// Calibrate against blinded human labels before trusting the grader, and report by slice.
function agreementBySlice(rows: { slice: string; human: number; grader: number }[]) {
  const bySlice = new Map<string, { agree: number; total: number }>();
  for (const row of rows) {
    const tally = bySlice.get(row.slice) ?? { agree: 0, total: 0 };
    tally.total += 1;
    if ((row.grader >= 0.8) === (row.human >= 0.8)) tally.agree += 1;
    bySlice.set(row.slice, tally);
  }
  return [...bySlice].map(([slice, t]) => ({ slice, agreement: t.agree / t.total }));
}
// Disagreements and high-impact cases go to people; the candidate never grades itself alone.

// Grade the trajectory as well as the answer. Dashboard trace grading does this for recorded
// traces; the same checks can run in CI over captured Responses output items.
interface TraceItem {
  type: "function_call" | "function_call_output" | "message";
  name?: string;
}

interface TrajectoryExpectation {
  allowedTools: string[];
  firstTool: string;
  maxCalls: number;
}

function gradeTrajectory(items: TraceItem[], expected: TrajectoryExpectation) {
  const calls = items.filter((item) => item.type === "function_call");
  return {
    onlyAllowedTools: calls.every((call) => expected.allowedTools.includes(call.name ?? "")),
    correctFirstTool: calls[0]?.name === expected.firstTool,
    withinCallBudget: calls.length <= expected.maxCalls,
    stoppedWithAnswer: items.at(-1)?.type === "message",
  };
}

interface CaseResult {
  caseId: string;
  slice: string;
  score: number;
  critical: boolean;
}

// Same cases, prompts, tools, budgets, and graders for both runs; honor the predeclared rule.
function compare(baseline: CaseResult[], candidate: CaseResult[]) {
  const before = new Map(baseline.map((r) => [r.caseId, r]));
  const critical = candidate.filter((r) => r.critical);
  if (critical.length) return { decision: "hold", critical: critical.map((r) => r.caseId) };
  const regressions = candidate.filter((r) => r.score < (before.get(r.caseId)?.score ?? 0));
  return { decision: regressions.length ? "review" : "ship", regressions: regressions.map((r) => r.caseId) };
}

// Allowlisted production event: identifiers, versions, and outcomes, not raw content.
interface ProductionEvent {
  traceId: string;
  requestId: string; // response._request_id
  appVersion: string;
  promptVersion: string;
  configuredModel: string;
  toolVersions: Record<string, string>;
  status: string;
  validation: "passed" | "failed";
  terminalState: string;
  latencyMs: number;
  inputTokens: number;
  outputTokens: number;
  userFeedback?: "helpful" | "not_helpful" | "reported";
}

// A reproducible failure becomes a regression case with provenance, after redaction and review.
function toRegressionCase(event: ProductionEvent, redactedTicket: string, reviewer: string) {
  return {
    case_id: `prod-${event.traceId}`,
    ticket_text: redactedTicket,
    slice: event.userFeedback === "reported" ? "user-reported" : "validation-failure",
    provenance: `trace ${event.traceId}; ${event.promptVersion}; ${event.configuredModel}; reviewed by ${reviewer}`,
    split: "dev",
  };
}

// Drift is tracked per version; a breach pages an owner, who decides containment or rollback.
function driftAlert(window: ProductionEvent[], baselineFailureRate: number) {
  if (window.length === 0) return null;
  const rate = window.filter((e) => e.validation === "failed").length / window.length;
  return rate > baselineFailureRate * 1.5 ? { page: "triage-eval-owner", rate, version: window[0].promptVersion } : null;
}
